package io.airtap.fixture.receiver;
import android.app.*;import android.content.*;import android.net.*;import android.os.*;import android.widget.*;import java.io.*;import java.security.*;import org.json.*;
public class ReceiverActivity extends Activity {
 Uri uri;ParcelFileDescriptor held;FileInputStream stream;TextView result;long readMs;
 void record(String event,boolean ok,String detail){try{JSONObject v=new JSONObject().put("event",event).put("ok",ok).put("detail",detail).put("time",System.currentTimeMillis()).put("read_ms",readMs);try(FileOutputStream out=openFileOutput("events.jsonl",MODE_APPEND)){out.write((v.toString()+"\n").getBytes());}runOnUiThread(()->result.setText(v.toString()));}catch(Exception ignored){}}
 String hash(InputStream in)throws Exception {long start=SystemClock.elapsedRealtime();ByteArrayOutputStream out=new ByteArrayOutputStream();byte[] b=new byte[4096];int n;while((n=in.read(b))>=0)out.write(b,0,n);readMs=SystemClock.elapsedRealtime()-start;return out.size()+":"+java.util.HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(out.toByteArray()));}
 public void onCreate(Bundle b){super.onCreate(b);LinearLayout view=new LinearLayout(this);view.setOrientation(1);setContentView(view);result=new TextView(this);view.addView(result);uri=getIntent().getParcelableExtra(Intent.EXTRA_STREAM,Uri.class);
  if(uri!=null)new Thread(()->{try{try(FileOutputStream out=openFileOutput("uri",MODE_PRIVATE)){out.write(uri.toString().getBytes());}held=getContentResolver().openFileDescriptor(uri,"r");stream=new FileInputStream(held.getFileDescriptor());record("received",true,hash(stream));}catch(Exception e){record("received",false,e.getClass().getSimpleName());}}).start();
  for(String label:new String[]{"Read held descriptor","Read new descriptor","Try write"}){Button x=new Button(this);x.setText(label);view.addView(x);x.setOnClickListener(v->{try{if(label.startsWith("Read held")){stream.getChannel().position(0);record("held_read",true,hash(stream));}else if(label.startsWith("Read new")){try(InputStream in=getContentResolver().openInputStream(uri)){record("new_read",true,hash(in));}}else{try(ParcelFileDescriptor fd=getContentResolver().openFileDescriptor(uri,"rw")){record("write",true,"unexpected");}}}catch(Exception e){record(label.startsWith("Read held")?"held_read":label.startsWith("Read new")?"new_read":"write",false,e.getClass().getSimpleName());}});}
 }
}
